{
  "category": "sketch",
  "tools": [
    {
      "name": "arduino_sketch",
      "description": "Manage Arduino sketches - create, open, and edit sketch files. Use get_content to read code, set_content to write code (changes are written to disk immediately and shown in the IDE). Use list_examples to find built-in examples, from_example to create a sketch from an example. File access is restricted to the sketchbook, built-in examples, and temporary sketches.",
      "parameters": {
        "action": {
          "type": "string",
          "enum": [
            "create",
            "open",
            "list",
            "get_content",
            "set_content",
            "get_files",
            "get_current",
            "list_examples",
            "from_example"
          ],
          "description": "The sketch operation to perform"
        },
        "path": {
          "type": "string",
          "description": "Path or file:// URI of a sketch folder or file (for open, get_content, set_content)"
        },
        "name": {
          "type": "string",
          "description": "Name for the new sketch (for create). Letters, digits, \"_\" and \"-\" only. Created in the sketchbook. Omit to create a temporary sketch."
        },
        "content": {
          "type": "string",
          "description": "Sketch content (for set_content action)"
        },
        "example_path": {
          "type": "string",
          "description": "Path to example (for from_example). Use list_examples to find available examples."
        },
        "category": {
          "type": "string",
          "description": "Filter examples by category: \"01.Basics\", \"02.Digital\", \"03.Analog\", etc. (for list_examples)"
        }
      },
      "required": [
        "action"
      ],
      "annotations": {
        "title": "Arduino sketches",
        "readOnlyHint": false,
        "destructiveHint": false
      }
    }
  ],
  "hint": "Use execute_tool with tool_name and params to execute a tool"
}
